2065	/*
2066	 * Continuous step "lane" background (方案A: 背景连续、块仍分明).
2067	 *
2068	 * Each content-type step-type record paints its --step-lane colour through a
2069	 * z-index:-1 ::before underlay that overflows ±7px vertically. Because
2070	 * .history-detail uses gap:14px between sibling records, two adjacent records
2071	 * of the SAME step each overflow 7px into the 14px gap and meet edge-to-edge
2072	 * at the gap mid-line, so the lane colour reads as one continuous band across
2073	 * the whole step region instead of a stack of disconnected islands. The
2074	 * records' own bubbles / cards / tool markers keep their borders and higher-
2075	 * alpha backgrounds untouched, so the blocks stay individually distinct.
2076	 *
2077	 * Status / DAG markers (.step-status-row / .group-status-marker) are excluded,
2078	 * exactly as the per-type colour rules above.
2079	 */
2080	.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {
2081	  position: relative;
2082	  /*
2083	   * Establish a stacking context on the record itself. Without this, the
2084	   * z-index:-1 ::before underlay below would NOT be contained by .conv-record
2085	   * (which is merely position:relative) and would instead resolve against the
2086	   * nearest ancestor that DOES form a stacking context (.history-view /
2087	   * #flow-view). The intervening panes (.history-detail-pane / .flow-main)
2088	   * carry an opaque `background: var(--bg)` that paints OVER a negative-z
2089	   * descendant pseudo, hiding the lane tint entirely. `isolation: isolate`
2090	   * forms a stacking context with no other side effects, so the underlay
2091	   * paints behind the record's own content but ABOVE the pane background,
2092	   * keeping the lane colour visible.
2093	   */
2094	  isolation: isolate;
2095	}
2096	.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before {
2097	  content: "";
2098	  position: absolute;
2099	  left: 0;
2100	  right: 0;
2101	  top: -7px;
2102	  bottom: -7px;
2103	  z-index: -1;
2104	  pointer-events: none;
2105	  background-color: var(--step-lane);
2106	}
2107	
2108	/*
2109	 * Boundary & container-edge suppression. The ±7px overflow must stay strictly
2110	 * INSIDE one step region: it must never cross a .history-step-header into a
2111	 * neighbouring step, nor bleed into the conversation area's top/bottom padding.
2112	 * This keeps the step-to-step boundary visually identical to before.
2113	 *
2114	 * - First block of a step (right after a header): no upward overflow.
2115	 * - Last block of a step (right before the next header): no downward overflow.
2116	 * - First / last child of the container: no overflow past the container edge.
2117	 *
2118	 * Degrades gracefully where :has() is unsupported: only a 7px same-step tail
2119	 * remains below a step's last block — still never crossing into the next step.

1	/*
2	 * Continuous step-lane background tests (Group G2).
3	 *
4	 * Loaded by tests/frontend/test_app_pure.mjs after its shared DOM stub is
5	 * installed. Exposes `registerStepLaneContinuityTests({app, check, findOne,
6	 * findAll})` so the parent harness drives the same check() reporter.
7	 *
8	 * This is a CSS-only feature (方案A: 背景连续、块仍分明): the per-step lane colour,
9	 * formerly painted as a per-record island background, is now carried on a
10	 * --step-lane custom property and rendered through a z-index:-1 ::before underlay
11	 * that overflows ±7px into the .history-detail gap:14px so adjacent same-step
12	 * records' lanes meet edge-to-edge and read as one continuous band. The
13	 * assertions are read-only string/rule checks against style.css.
14	 *
15	 * Coverage:
16	 *   (a) The 13 per-type rules carry --step-lane (with their original colour /
17	 *       alpha) and keep their border-left-color, and no longer paint `background`
18	 *       directly on the record box.
19	 *   (b) A shared ::before underlay rule exists with top:-7px / bottom:-7px and
20	 *       z-index:-1, consuming background-color:var(--step-lane).
21	 *   (c) Boundary / container-edge overflow-suppression rules exist (first block
22	 *       no upward overflow, last block no downward overflow, container first /
23	 *       last child no overflow past the edge).
24	 *   (d) The geometry rule still excludes .step-status-row / .group-status-marker.
25	 */
26	import assert from "node:assert/strict";
27	import fs from "node:fs";
28	import path from "node:path";
29	import { fileURLToPath } from "node:url";
30	
31	const HERE = path.dirname(fileURLToPath(import.meta.url));
32	const STYLE_CSS = path.join(
33	  HERE, "..", "..", "src", "se3", "server", "static", "style.css");
34	const CSS = fs.readFileSync(STYLE_CSS, "utf8");
35	
36	// The 13 content step types and their original lane colour/alpha (must be
37	// preserved byte-for-byte, only moved from `background:` to `--step-lane:`).
38	const PER_TYPE = [
39	  ["discovery", "rgba(91, 143, 214, 0.07)"],
40	  ["analyze", "rgba(63, 169, 191, 0.07)"],
41	  ["plan", "rgba(138, 130, 224, 0.08)"],
42	  ["confirm", "rgba(111, 134, 201, 0.07)"],
43	  ["implement", "rgba(87, 168, 106, 0.07)"],
44	  ["test", "rgba(63, 174, 154, 0.07)"],
45	  ["self_check", "rgba(200, 154, 70, 0.08)"],
46	  ["verify_spec", "rgba(208, 130, 78, 0.08)"],
47	  ["update_spec", "rgba(84, 174, 196, 0.07)"],
48	  ["spec_gate", "rgba(194, 161, 63, 0.08)"],
49	  ["version_analyze", "rgba(168, 127, 196, 0.08)"],
50	  ["commit", "rgba(121, 168, 63, 0.07)"],
51	  ["summarize", "rgba(130, 139, 152, 0.09)"],
52	];
53	
54	// Extract the body `{...}` of the first rule whose selector contains `needle`.
55	function ruleBody(css, needle) {
56	  const at = css.indexOf(needle);
57	  assert.notEqual(at, -1, `missing rule containing: ${needle}`);
58	  const open = css.indexOf("{", at);
59	  assert.notEqual(open, -1, `no '{' after: ${needle}`);
60	  const close = css.indexOf("}", open);
61	  assert.notEqual(close, -1, `no '}' after: ${needle}`);
62	  return css.slice(open + 1, close);
63	}
64	
65	export function registerStepLaneContinuityTests(ctx) {
66	  const { check } = ctx;
67	
68	  // ---- (a) per-type rules carry --step-lane, keep border-left, drop bg ------
69	  for (const [type, colour] of PER_TYPE) {
70	    check(`G2 step-type-${type} carries --step-lane and keeps border-left`, () => {
71	      const sel =
72	        `.history-detail .conv-record.step-type-${type}:not(.step-status-row):not(.group-status-marker)`;
73	      const body = ruleBody(CSS, sel);
74	      assert.ok(
75	        body.includes(`--step-lane: ${colour}`),
76	        `${type} rule must set --step-lane: ${colour}`);
77	      assert.ok(
78	        body.includes(`border-left-color: var(--step-${type})`),
79	        `${type} rule must keep its border-left-color`);
80	      // No longer paints a plain `background` on the record box itself.
81	      assert.ok(
82	        !/(^|[\s;{])background\s*:/.test(body),
83	        `${type} rule must not paint background directly (lane moved to ::before)`);
84	    });
85	  }
86	
87	  // ---- (b) shared ::before underlay with ±7px overflow and z-index:-1 -------
88	  check("G2 step-type ::before underlay overflows ±7px under content", () => {
89	    const body = ruleBody(
90	      CSS,
91	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`);
92	    assert.ok(body.includes("top: -7px"), "::before must overflow top: -7px");
93	    assert.ok(body.includes("bottom: -7px"), "::before must overflow bottom: -7px");
94	    assert.ok(body.includes("left: 0"), "::before must span left: 0");
95	    assert.ok(body.includes("right: 0"), "::before must span right: 0");
96	    assert.ok(/z-index:\s*-1/.test(body), "::before must sit at z-index: -1 (below content)");
97	    assert.ok(
98	      body.includes("background-color: var(--step-lane)"),
99	      "::before must paint background-color: var(--step-lane)");
100	    assert.ok(body.includes('content: ""'), "::before must set content");
101	    assert.ok(/position:\s*absolute/.test(body), "::before must be absolutely positioned");
102	  });
103	
104	  check("G2 step-type record establishes a positioning context", () => {
105	    const body = ruleBody(
106	      CSS,
107	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`);
108	    assert.ok(/position:\s*relative/.test(body),
109	      "content step-type record must be position: relative for the ::before underlay");
110	  });
111	
112	  // ---- (b2) visibility contract: record must form a STACKING CONTEXT --------
113	  // Pins the fix for the self-check critical issue. The lane is painted by a
114	  // z-index:-1 ::before underlay. If .conv-record only has position:relative
115	  // (no stacking context), that negative-z pseudo resolves against the nearest
116	  // ancestor stacking context (.history-view / #flow-view) and is drawn BEHIND
117	  // the opaque `background: var(--bg)` of the intervening panes
118	  // (.history-detail-pane / .flow-main) — so the lane renders nothing. The
119	  // record MUST therefore form its own stacking context (isolation: isolate,
120	  // or an explicit non-auto z-index) so the underlay paints behind the
121	  // record's own content but ABOVE the pane background and stays visible.
122	  check("G2 step-type record forms a stacking context so the underlay is visible", () => {
123	    const body = ruleBody(
124	      CSS,
125	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`);
126	    const formsStackingContext =
127	      /isolation:\s*isolate/.test(body) ||
128	      // An explicit non-auto z-index on a positioned element also forms one.
129	      /z-index:\s*-?\d/.test(body);
130	    assert.ok(
131	      formsStackingContext,
132	      "content step-type record must form a stacking context (isolation: isolate " +
133	      "or an explicit z-index) so the z-index:-1 lane underlay paints above the " +
134	      "ancestor pane's opaque var(--bg) background instead of being hidden behind it");
135	  });
136	
137	  // The intervening panes really do carry an opaque background — this is the
138	  // ancestor that would hide an un-contained underlay. Lock it so the test
139	  // above keeps its rationale: if these ever become transparent the stacking
140	  // requirement could be relaxed, but today it is mandatory.
141	  check("G2 intervening panes carry an opaque var(--bg) background", () => {
142	    const detailPane = ruleBody(CSS, ".history-detail-pane");
143	    assert.ok(/background:\s*var\(--bg\)/.test(detailPane),
144	      ".history-detail-pane must carry the opaque var(--bg) background the underlay must paint above");
145	  });
146	
147	  // ---- (c) boundary / container-edge suppression ---------------------------
148	  // The base ::before underlay rule carries
149	  // `[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)`,
150	  // giving it specificity (0,5,1). The four boundary-suppression rules below
151	  // must WIN the cascade over it to reset the ±7px overflow at step/container
152	  // edges. Two things make them win and BOTH must be locked, or the reset can
153	  // silently regress (a single-`.history-detail` selector is only (0,3,1), so
154	  // its top:0/bottom:0 would lose to the base ::before and the lane would bleed
155	  // across the .history-step-header into the neighbouring step):
156	  //   1. equal-or-greater specificity — achieved by tripling `.history-detail`
157	  //      (`.history-detail.history-detail.history-detail …`) to reach (0,5,1);
158	  //   2. later source order than the base ::before rule, to win the tie.
159	  // The single-`.history-detail` substring is found inside the tripled selector
160	  // regardless, so the needles below carry the full tripled prefix and we also
161	  // assert each rule appears AFTER the base ::before rule in source order.
162	  const TRIPLE = ".history-detail.history-detail.history-detail";
163	  const baseBeforeSel =
164	    `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`;
165	  const baseBeforeAt = CSS.indexOf(baseBeforeSel);
166	  assert.notEqual(baseBeforeAt, -1, "base ::before underlay rule must exist");
167	
168	  function boundaryRule(needle, edge) {
169	    // Must use the tripled prefix (specificity (0,5,1) >= base (0,5,1)).
170	    const at = CSS.indexOf(needle);
171	    assert.notEqual(
172	      at, -1,
173	      `boundary rule must use the specificity-tripled prefix: ${needle}`);
174	    // Must come AFTER the base ::before rule so it wins the specificity tie.
175	    assert.ok(
176	      at > baseBeforeAt,
177	      `boundary rule must appear later in source order than the base ::before ` +
178	      `rule to win the cascade tie: ${needle}`);
179	    const body = ruleBody(CSS, needle);
180	    assert.ok(
181	      new RegExp(`${edge}:\\s*0`).test(body),
182	      `boundary rule must reset ${edge} to 0: ${needle}`);
183	  }
184	
185	  check("G2 step first block does not overflow upward across the header", () => {
186	    boundaryRule(`${TRIPLE} .history-step-header + .conv-record::before`, "top");
187	  });
188	  check("G2 step last block does not overflow downward across the next header", () => {
189	    boundaryRule(`${TRIPLE} .conv-record:has(+ .history-step-header)::before`, "bottom");
190	  });
191	  check("G2 container first/last child does not overflow past the edge", () => {
192	    boundaryRule(`${TRIPLE} > .conv-record:first-child::before`, "top");
193	    boundaryRule(`${TRIPLE} > .conv-record:last-child::before`, "bottom");
194	  });
195	
196	  // Pin that the tripling is load-bearing: a single-`.history-detail` boundary
197	  // selector (specificity (0,3,1)) would LOSE the cascade to the base ::before
198	  // rule (0,5,1). Assert the boundary rules do NOT degrade to a bare
199	  // single-`.history-detail` form, so a future edit dropping the tripling fails.
200	  check("G2 boundary rules keep the load-bearing specificity tripling", () => {
201	    // Strip /* ... */ comments first: the explanatory comment above the rules
202	    // deliberately quotes the single-`.history-detail` anti-pattern as an
203	    // example, which would otherwise trip the "must be tripled" scan below.
204	    const CSS_NC = CSS.replace(/\/\*[\s\S]*?\*\//g, "");
205	    for (const needle of [
206	      " .history-step-header + .conv-record::before",
207	      " .conv-record:has(+ .history-step-header)::before",
208	      " > .conv-record:first-child::before",
209	      " > .conv-record:last-child::before",
210	    ]) {
211	      // Every occurrence of this boundary tail must be preceded by the tripled
212	      // prefix — never a bare single `.history-detail`.
213	      let from = 0;
214	      let found = false;
215	      for (;;) {
216	        const at = CSS_NC.indexOf(needle, from);
217	        if (at === -1) break;
218	        found = true;
219	        const before = CSS_NC.slice(0, at);
220	        assert.ok(
221	          before.endsWith(TRIPLE),
222	          `boundary rule '${needle.trim()}' must be prefixed by the tripled ` +
223	          `'${TRIPLE}' (specificity (0,5,1)); a single '.history-detail' ` +
224	          `(0,3,1) would lose the cascade to the base ::before underlay`);
225	        from = at + needle.length;
226	      }
227	      assert.ok(found, `boundary rule tail must exist: ${needle.trim()}`);
228	    }
229	  });
230	
231	  // ---- (d) status / DAG markers stay excluded ------------------------------
232	  check("G2 lane geometry still excludes status / group markers", () => {
233	    // Both the position:relative base rule and the ::before rule must carry the
234	    // :not(.step-status-row):not(.group-status-marker) exclusion.
235	    const baseSel =
236	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker) {`;
237	    const beforeSel =
238	      `.history-detail .conv-record[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)::before`;
239	    assert.notEqual(CSS.indexOf(baseSel), -1,
240	      "base geometry rule must exclude .step-status-row/.group-status-marker");
241	    assert.notEqual(CSS.indexOf(beforeSel), -1,
242	      "::before geometry rule must exclude .step-status-row/.group-status-marker");
243	  });
244	}
245

2118	 * Degrades gracefully where :has() is unsupported: only a 7px same-step tail
2119	 * remains below a step's last block — still never crossing into the next step.
2120	 *
2121	 * Specificity note: the base ::before underlay rule above carries
2122	 * `[class*="step-type-"]:not(.step-status-row):not(.group-status-marker)`,
2123	 * giving it specificity (0,5,1). A naive boundary selector such as
2124	 * `.history-detail .history-step-header + .conv-record::before` is only
2125	 * (0,3,1), so its `top:0` / `bottom:0` would LOSE the cascade and the
2126	 * ±7px overflow would stand — bleeding the lane colour across the step
2127	 * boundary. We therefore repeat the `.history-detail` class (a no-op for
2128	 * matching — an element either has the class or not) to lift each boundary
2129	 * rule to (0,5,1), equal to the base rule; since these rules come later in
2130	 * source order, they win the tie and correctly reset the overflow to 0.
2131	 */
2132	.history-detail.history-detail.history-detail .history-step-header + .conv-record::before { top: 0; }
2133	.history-detail.history-detail.history-detail .conv-record:has(+ .history-step-header)::before { bottom: 0; }
2134	.history-detail.history-detail.history-detail > .conv-record:first-child::before { top: 0; }
2135	.history-detail.history-detail.history-detail > .conv-record:last-child::before { bottom: 0; }
2136	
2137	/* The step-header separator row is the explicit boundary between two step
2138	 * regions. Give it a little extra breathing room above (never before the very
2139	 * first header) so the colour change between lanes is unmistakable; the title
2140	 * keeps its existing reverse-block look. Scoped to the conversation so the
2141	 * history LIST is untouched. */
2142	.history-detail .history-step-header { margin-top: 4px; }
2143	.history-detail .history-step-header:first-child { margin-top: 0; }
2144	
2145	/* -- step report card ----------------------------------------------- */
2146	/*
2147	 * Default-expanded report card mirroring the CLI's per-step Rich Panel.
2148	 * Sits inside the .history-step container directly after the raw
2149	 * step_completed chip. No max-height — long reports scroll with the
2150	 * page, not inside a captive viewport (see the running-flow-console
2151	 * spec: per-block height caps are not allowed).
2152	 */
2153	.step-report {
2154	  border: 1px solid var(--border);
2155	  border-left: 3px solid var(--accent);
2156	  border-radius: 7px;
2157	  background: var(--bg-card);
2158	  margin: 4px 0;
2159	  display: flex;
2160	  flex-direction: column;
2161	}
2162	/* Match each report card's left border to its step's grouping accent so the
2163	 * card reads as the "result/summary" of the same coloured step region. */
2164	.step-report.kind-discovery       { border-left-color: var(--step-discovery); }
2165	.step-report.kind-analyze         { border-left-color: var(--step-analyze); }
2166	.step-report.kind-plan            { border-left-color: var(--step-plan); }
2167	.step-report.kind-confirm         { border-left-color: var(--step-confirm); }

