26	import assert from "node:assert/strict";
27	import fs from "node:fs";
28	import path from "node:path";
29	import { fileURLToPath } from "node:url";
30	
31	const HERE = path.dirname(fileURLToPath(import.meta.url));
32	const STYLE_CSS = path.join(
33	  HERE, "..", "..", "src", "se3", "server", "static", "style.css");
34	const CSS = fs.readFileSync(STYLE_CSS, "utf8");
35	
36	// The 13 content step types and their original lane colour/alpha (must be
37	// preserved byte-for-byte, only moved from `background:` to `--step-lane:`).
38	const PER_TYPE = [
39	  ["discovery", "rgba(91, 143, 214, 0.07)"],
40	  ["analyze", "rgba(63, 169, 191, 0.07)"],
41	  ["plan", "rgba(138, 130, 224, 0.08)"],
42	  ["confirm", "rgba(111, 134, 201, 0.07)"],
43	  ["implement", "rgba(87, 168, 106, 0.07)"],
44	  ["test", "rgba(63, 174, 154, 0.07)"],
45	  ["self_check", "rgba(200, 154, 70, 0.08)"],
46	  ["verify_spec", "rgba(208, 130, 78, 0.08)"],
47	  ["update_spec", "rgba(84, 174, 196, 0.07)"],
48	  ["spec_gate", "rgba(194, 161, 63, 0.08)"],
49	  ["version_analyze", "rgba(168, 127, 196, 0.08)"],
